import os
import boto3
from datetime import datetime, timedelta, timezone
from typing import Dict, Any, List

def compare_metric_values(instance_id_a: str, instance_id_b: str, window_minutes: int = 60) -> Dict[str, Any]:
    cloudwatch = boto3.client(
        "cloudwatch",
        region_name="us-east-1",
        aws_access_key_id=os.getenv("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.getenv("AWS_SECRET_ACCESS_KEY")
    )

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=window_minutes)

    response = cloudwatch.get_metric_data(
        MetricDataQueries=[
            {
                "Id": "res_a",
                "MetricStat": {
                    "Metric": {
                        "Namespace": "AWS/EC2",
                        "MetricName": "CPUUtilization",
                        "Dimensions": [{"Name": "InstanceId", "Value": instance_id_a}]
                    },
                    "Period": 300,
                    "Stat": "Average",
                    "Unit": "Percent"
                }
            },
            {
                "Id": "res_b",
                "MetricStat": {
                    "Metric": {
                        "Namespace": "AWS/EC2",
                        "MetricName": "CPUUtilization",
                        "Dimensions": [{"Name": "InstanceId", "Value": instance_id_b}]
                    },
                    "Period": 300,
                    "Stat": "Average",
                    "Unit": "Percent"
                }
            }
        ],
        StartTime=start_time,
        EndTime=end_time
    )

    metric_results: List[Dict[str, Any]] = response.get("MetricDataResults", [])
    series_a: List[float] = next((r.get("Values", []) for r in metric_results if r.get("Id") == "res_a"), [])
    series_b: List[float] = next((r.get("Values", []) for r in metric_results if r.get("Id") == "res_b"), [])

    avg_a = sum(series_a) / len(series_a) if series_a else 0.0
    avg_b = sum(series_b) / len(series_b) if series_b else 0.0

    return {
        "window_start": start_time.isoformat(),
        "window_end": end_time.isoformat(),
        "instance_a_avg_cpu_percent": round(avg_a, 2),
        "instance_b_avg_cpu_percent": round(avg_b, 2),
        "absolute_difference": round(abs(avg_a - avg_b), 2),
        "instance_a_data_points": len(series_a),
        "instance_b_data_points": len(series_b),
        "comparison_window_minutes": window_minutes
    }
